``` php
// Models:

class PdfPlacesTable extends Table
{
    public function initialize(array $config)
    {
        parent::initialize($config);
        $this->table('pdf_places');
        $this->primaryKey('id');
        $this->hasMany('PdfDocumentsPub', [
            'foreignKey' => 'pdf_place_id'
        ]);
        $this->hasMany('LatestPdfDocumentsPub', [
            'className' => 'PdfDocumentsPub',
            'propertyName' => 'myPropertyName', //why this key is not available under _matchingData array()?
            'foreignKey' => false
        ]);
    }
    public function beforeFind(Event $event, Query $query, ArrayObject $options, $primary)
    {
        $query->where([
            'PdfPlaces.com_id' => 10543,
        ]);
        return $query;
    }
}
class PdfDocumentsPubTable extends Table
{
    public function initialize(array $config)
    {
        parent::initialize($config);
        $this->table('pdf_documents_pub');
        $this->primaryKey('id');
        $this->belongsTo('PdfPlaces', [
            'foreignKey' => 'pdf_place_id',
            'joinType' => 'INNER'
        ]);
    }
}
